import uuid from "uuid/v4";
//import { MICROSOFT_SERVICE, getService } from "../aptero/module/axolotis/AxolotisSystem";//TODO invert dep for this MSAuth depends on Phoenix Auth
//import { msPassiveLoginCheckNeeded } from "../aptero/module/microsoft/MsTeams";
import { AuthInterface } from "@root/lib/modules/phoenixAuth/AuthInterface";
//TODO invert dep for this MSAuth depends on Phoenix Auth

export default class AuthChannel {
  private store: any;
  private socket: any;
  _signedIn: any;
  authInterface: AuthInterface;

  constructor(store) {
    this.store = store;
    this.socket = null;
    this._signedIn = !!this.store.state.credentials.token;
    this.authInterface.passiveLogIn();
    /*if(msPassiveLoginCheckNeeded()) {
      getService(MICROSOFT_SERVICE).then(async service => {
        await service.getLoginService().passiveLogin();
        this.microsoftLoginService = service;
      })
    }*/
  }

  setSocket = socket => {
    this.socket = socket;
  };

  get email() {
    // (this.microsoftLoginService && (this.microsoftLoginService.getUserAccount() && (this.microsoftLoginService.getUserAccount().mail)))
    return (this.authInterface.getAccount() && this.authInterface.getAccount().email) || this.store.state.credentials.email;
  }

  get signedIn() {
    return this._signedIn;
  }

  signOut = async hubChannel => {
    if (hubChannel) {
      await hubChannel.signOut();
    }
    this.store.update({ credentials: { token: null, email: null } });
    await this.store.resetToRandomDefaultAvatar();
    this._signedIn = false;
    await this.authInterface.signOut();
    /*if(this.microsoftLoginService) {
      this.microsoftLoginService.getLoginService().logout();
    }*/
  };

  verifyAuthentication(authTopic, authToken, authPayload) {
    const channel = this.socket.channel(authTopic);
    return new Promise((resolve, reject) => {
      channel.onError(() => {
        channel.leave();
        reject();
      });

      channel
        .join()
        .receive("ok", () => {
          channel.on("auth_credentials", async ({ credentials: token, payload: payload }) => {
            await this.handleAuthCredentials(payload.email, token, null);
            resolve(true);
          });

          channel.push("auth_verified", {
            token: authToken,
            payload: authPayload
          });
        })
        .receive("error", reject);
    });
  }

  async startAuthentication(email, hubChannel) {
    const channel = this.socket.channel(`auth:${uuid()}`);
    await new Promise((resolve, reject) =>
      channel
        .join()
        .receive("ok", resolve)
        .receive("error", reject)
    );

    const authComplete = new Promise(resolve =>
      channel.on("auth_credentials", async ({ credentials: token }) => {
        await this.handleAuthCredentials(email, token, hubChannel);
        resolve(true);
      })
    );

    channel.push("auth_request", { email, origin: "hubs" });

    // Returning an object with the authComplete promise since we want the caller to wait for the above await but not
    // for authComplete.
    return { authComplete };
  }

  async handleAuthCredentials(email, token, hubChannel) {
    this.store.update({ credentials: { email, token } });

    if (hubChannel) {
      await hubChannel.signIn(token);
    }

    this._signedIn = true;
  }
}
